#include <iostream>
#include <cmath>
using namespace std;

long long count_res(int n) {
    long long results = 1;
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        total += results;
        results *= 2;
    }
    return total;
}

int main() {
    int height, position;
    cin >> height >> position;

    long long answer = 0;
    long long left_bound = 1;
    long long right_bound = (1LL << height);
    int current_height = height;
    char direction = 'L';

    for (int i = 0; i < height; ++i) {
        long long mid = (left_bound + right_bound) / 2;
        if (direction == 'L') {
            if (position > mid) {
                answer += count_res(current_height) + 1;
                left_bound = mid + 1;
            } else if (position < mid) {
                long long sum_bounds = left_bound + right_bound;
                long long adjustment = (sum_bounds % 2 != 0) ? 1 : 0;
                right_bound = mid + adjustment - 1;
                answer += 1;
                direction = 'R';
            }
            current_height -= 1;
        } else {
            if (position < mid) {
                long long sum_bounds = left_bound + right_bound;
                long long adjustment = (sum_bounds % 2 != 0) ? 1 : 0;
                right_bound = mid + adjustment - 1;
                answer += count_res(current_height) + 1;
            } else if (position > mid) {
                answer += 1;
                left_bound = mid + 1;
                direction = 'L';
            }
            current_height -= 1;
        }
    }
    cout << answer << "\n";
    return 0;
}

